         float EvalIntensityCurve(float2 id, float amzLocal_time)
         {
             amzLocal_time += Hash(id.yx * 1.733);
             float iTime = floor(amzLocal_time);
             float fTime = fract(amzLocal_time);
             float h = Hash(float3(id, iTime));
             h *= h;
             h *= h;
             float falloff = 1.0 - Pow2(fTime * 2.0 - 1.0);
             {
                 const float f = 100.0;
                 const float d = 1.0 / (exp2(f) - 1.0);
                 falloff = ((exp2(falloff * f)) * (d) + (-d));
             }
             return h * falloff*1.0;
         }
         float GlowKern1(float x, float s)
         {
             float rx = sqrt(x);
             return (exp(-s * rx) * s) / (2.0 * rx);
         }
         float GlowKern2(float x, float s)
         {
             float rx = sqrt(x);
             return s / (2.0 * Pow2(1.0 + s * rx) * rx);
         }
         float GlowKern3(float x, float s)
         {
             return s / Pow3(1.0 + s * x);
         }
         float GlowKern4(float x, float c)
         {
             return c * inversesqrt(x * Pow3(x + c)) * 0.5;
         }
         float CurveU(float x, float u)
         {
             return (u - u * x) / (u + x);
         }
         float EvalGlow3(float2 uv, float2 off, float amzLocal_time)
         {
             float2 iUV = floor(uv) + off;
             float2 fUV = fract(uv) - off;
             float2 fUV2 = fUV * 2.0 - 1.0;
             float dist2 = SqrLen(fUV2);
             float l = length(fUV2);
             l = max(0.0, l - 0.7);
             float glow = 0.0;
             glow = GlowKern3(l, 1.2);
             glow = clamp(glow, 0.0, 1.0);
             glow *= clamp(1.0 - Pow2(l*0.25), 0.0, 1.0);
             return EvalIntensityCurve(iUV.xy, amzLocal_time) * glow;
         }
         float PlotDot(float2 sp, float2 dp, float dr)
